head.script:
 	  // DistinctValue object
	  function DistinctValue( value, occurrences ){
	    this.value       = value;
	    this.occurrences = occurrences;
	    this.increment   = function(){ this.occurrences++; };
	  }

	  function equalValue( e ){
	    //console.log( e.value+" "+this.value );
	    return ( e.value == this.value );
	  }

	  function collectDistinctValues(){
	    //console.log( "In collectDistinctValues" );
  	    var dv=document.getElementsByClassName("distinct_values");
	    //console.log( "DistinctValues field "+dv+" "+dv.length );
  	    for ( var i=0; i < dv.length; i++ ){
  	      var values=dv[i].parentNode.getElementsByClassName("value");
  	      var distinctValues = new Array();
  	      for ( var j=0; j < values.length; j++ ){
	        var value=( values[j].innerHTML.length==0 ? String.fromCharCode(0x2205) : values[j].innerHTML ) // an empty set symbol if empty
	        var index = distinctValues.findIndex( equalValue, new DistinctValue( value, 0 ) );
  	        if   ( index < 0 ) distinctValues.push( new DistinctValue( value, 1 ) );
  	        else                  distinctValues[index].increment();
  	      }
	      //console.log( "DistinctValues array "+distinctValues+" "+distinctValues.length );
	      if ( distinctValues.length > 0 ){
	        if ( isNaN( distinctValues[0].value ) ) distinctValues.sort();
	        else                                    distinctValues.sort(function(a,b){return a.value-b.value;});
	      }
    	      for ( var j=0; j < distinctValues.length; j++ ){
   	        // dv[i].innerHTML+=distinctValues[j]+" ";
		var spanElem    = document.createElement("span");
		var classAttr   = document.createAttribute("class");
		var onclickAttr = document.createAttribute("onclick");
		var titleAttr   = document.createAttribute("title");
		var textNode    = document.createTextNode( distinctValues[j].value );
		var spaceNode   = document.createTextNode( " " );
		classAttr.value   = "distinct_value";
		onclickAttr.value = "highlightValues(this)";
		titleAttr.value   = distinctValues[j].occurrences+" occurrences of value "+distinctValues[j].value+". Click to highlight them.";
		spanElem.appendChild( textNode );
		spanElem.setAttributeNode( classAttr );
		spanElem.setAttributeNode( onclickAttr );
		spanElem.setAttributeNode( titleAttr );
		dv[i].appendChild( spaceNode );
		dv[i].appendChild( spanElem );
	      }
	      if ( i%2 ){
	        dv[i].parentNode.classList.add( "shaded_row" );
              }
	      else{
	        var fieldsInRow = dv[i].parentNode.children;
	        var previousRing = "ME+S/R";
		var shadeColumn = false;
	        for ( var j=0; j < fieldsInRow.length; j++ ){
		  var thisRing = fieldsInRow[j].title.substring(1,6);
		  if ( thisRing != previousRing ){
		    shadeColumn = ! shadeColumn;
		    previousRing = thisRing;
		  }
		  if ( shadeColumn ) fieldsInRow[j].classList.add( "shaded_col" );
		}
	      }
  	    }
  	  }

	  function highlightValues(elem){
	    // console.log( "clicked elem "+elem );  
            var distinctValues = document.getElementsByClassName("distinct_value");
  	    for ( var i=0; i < distinctValues.length; i++ ){
	      distinctValues[i].classList.remove("highlighted");
	    }
	    var fields = document.getElementsByClassName("value");
  	    for ( var i=0; i < fields.length; i++ ){
	      fields[i].classList.remove("highlighted");
	    }
	    elem.classList.add("highlighted");
	    // console.log( "clicked class "+elem.className );  
	    var fieldsInRow = elem.parentNode.parentNode.getElementsByClassName("value");
  	    for ( var i=0; i < fieldsInRow.length; i++ ){
	      if ( fieldsInRow[i].innerHTML == elem.innerHTML
	           || ( fieldsInRow[i].innerHTML.length == 0 &&
	                elem.innerHTML == String.fromCharCode(0x2205)  ) ){
	            fieldsInRow[i].classList.add("highlighted");
		    // console.log( "fieldsInRow["+i+"].className "+fieldsInRow[i].className );
	      }
	    }

	  }
